          <span class="item-icon" v-html="item.icon"></span>
          <span class="item-value">{{ item.value }}</span>
        </div>
        <div class="item-btn" :class="{ 'gap20': isMobile }">
          <el-icon id="store-contact-copy" class="item-copy" @click.stop.prevent="copyContact(item.key, item.value)">
            <Check v-if="contactCopyVisible===item.key" />
            <CopyDocument v-else />
          </el-icon>
          <a
            v-if="isMobile"
            :href="item.href"
            target="_blank"
            class="share"
            id="store-contact-click"
            @click="clickContact()"
          >
