          </a>
        </div>
      </a>
    </div>
    <el-link v-if="hasOverflow" class="store-contact-more" :class="{ 'is-expanded': expanded }" type="primary" underline="never" @click="onMoreContact">
      {{ $t('orders.orderItemButtonMore') }}
      <el-icon class="more-icon">
        <!-- Figma: chevron-down（展开时旋转 180° 变为 chevron-up） -->
        <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
